function SidebarMenuButton({
  className,
  isActive = false,
  size = "default",
  tooltip,
  render,
  children,
  ...props
}: useRender.ComponentProps<"button"> &
  VariantProps<typeof sidebarMenuButtonVariants> & {
    isActive?: boolean
    tooltip?: string
  }) {
  const { state, isMobile, side } = useSidebar()
  const buttonSize = size === "sm" ? "sm" : size === "lg" ? "lg" : "default"
  const showTooltip = state === "collapsed" && !isMobile

  // Always the same tree when a tooltip is set: switching wrappers on collapse
  // would remount the row and cut its label fade.
  if (tooltip) {
    return (
      <Tooltip disabled={!showTooltip}>
        <TooltipTrigger
          render={
            <SidebarMenuButtonPrimitive
              className={className}
              isActive={isActive}
              size={buttonSize}
              render={render}
              {...props}
            />
          }
        >
          {children}
        </TooltipTrigger>
        <TooltipContent side={side === "right" ? "left" : "right"}>
          {tooltip}
        </TooltipContent>
      </Tooltip>
    )
  }

  return (
    <SidebarMenuButtonPrimitive
      className={className}
      isActive={isActive}
      size={buttonSize}
      render={render}
      {...props}
    >
      {children}
    </SidebarMenuButtonPrimitive>
  )
}

