import * as React from "react"
import { SquareTerminalIcon } from "lucide-react"

import { CopyButton } from "@/components/ui/CopyButton"
import { Trace, TraceContent, TraceTrigger, type TraceStatus } from "@/components/ui/Trace"
import { cn } from "@/lib/utils"

/**
 * A command the agent runs and its output as it streams. Ink on a dark pane
 * in both themes, like a real terminal; the exit code sets the status.
 */
function Terminal({
  command,
  output = "",
  status,
  exitCode,
  cwd,
  maxHeight = "16rem",
  defaultOpen = true,
  className,
  ...props
}: Omit<React.ComponentProps<typeof Trace>, "variant" | "status" | "children"> & {
  command: string
  output?: string
  /** Running until an exit code arrives, unless set. */
  status?: TraceStatus
  exitCode?: number
  cwd?: string
  maxHeight?: string
}) {
  const resolved: TraceStatus =
    status ?? (exitCode === undefined ? "running" : exitCode === 0 ? "done" : "error")
  const bodyRef = React.useRef<HTMLPreElement>(null)

  // Follow the output while it streams.
  React.useEffect(() => {
    const body = bodyRef.current
    if (body && resolved === "running") body.scrollTop = body.scrollHeight
  }, [output, resolved])

  return (
    <Trace
      data-slot="terminal"
      variant="card"
      status={resolved}
      defaultOpen={defaultOpen}
      className={className}
      {...props}
    >
      <TraceTrigger
        icon={<SquareTerminalIcon />}
        meta={exitCode !== undefined ? <span className="font-mono text-[11px]">exit {exitCode}</span> : undefined}
      >
        <span className="font-mono">{command}</span>
      </TraceTrigger>
      <TraceContent>
        <div className="relative bg-neutral-950 text-neutral-100">
          <CopyButton
            value={`$ ${command}\n${output}`}
            size="icon-xs"
            label="Copy output"
            className="absolute end-1.5 top-1.5 text-neutral-400 hover:bg-white/10 hover:text-neutral-100"
          />
          <pre
            ref={bodyRef}
            tabIndex={0}
            aria-live={resolved === "running" ? "polite" : undefined}
            className="m-0 overflow-auto p-3 pe-10 font-mono text-[12px] leading-5 whitespace-pre-wrap outline-none focus-visible:ring-3 focus-visible:ring-ring/40 focus-visible:ring-inset"
            style={{ maxHeight }}
          >
            <span className="text-neutral-500 select-none">{cwd ? `${cwd} ` : ""}$ </span>
            <span className="text-neutral-50">{command}</span>
            {"\n"}
            <span className={cn(resolved === "error" ? "text-red-300" : "text-neutral-300")}>{output}</span>
            {resolved === "running" ? (
              <span aria-hidden className="ms-0.5 inline-block h-3.5 w-1.5 translate-y-0.5 animate-pulse bg-neutral-300" />
            ) : null}
          </pre>
        </div>
      </TraceContent>
    </Trace>
  )
}

export { Terminal }

"use client"

import * as React from "react"
import { CircleDashedIcon, FlaskConicalIcon } from "lucide-react"

import { Trace, TraceContent, TraceStatusIcon, TraceTrigger, type TraceStatus } from "@/components/ui/Trace"
import { cn } from "@/lib/utils"

type TestCase = {
  name: string
  status: "passed" | "failed" | "skipped"
  /** Milliseconds. */
  duration?: number
  error?: string
}

type TestSuite = { name: string; tests: TestCase[] }

const toTrace: Record<TestCase["status"], TraceStatus> = {
  passed: "done",
  failed: "error",
  skipped: "pending",
}

/**
 * A test run: counts and a bar on the row, then each suite. Suites with a
 * failure open by default and show the error under the test.
 */
function TestResults({
  suites,
  running = false,
  title = "Tests",
  className,
  defaultOpen = true,
  ...props
}: Omit<React.ComponentProps<typeof Trace>, "variant" | "status" | "children" | "title"> & {
  suites: TestSuite[]
  running?: boolean
  title?: React.ReactNode
}) {
  const tests = suites.flatMap((suite) => suite.tests)
  const count = (status: TestCase["status"]) => tests.filter((test) => test.status === status).length
  const passed = count("passed")
  const failed = count("failed")
  const skipped = count("skipped")
  const status: TraceStatus = running ? "running" : failed > 0 ? "error" : "done"
  const total = tests.length || 1

  return (
    <Trace data-slot="test-results" variant="card" status={status} defaultOpen={defaultOpen} className={className} {...props}>
      <TraceTrigger
        icon={<FlaskConicalIcon />}
        label={title}
        showStatus={false}
        meta={
          <span className="flex items-center gap-2 font-mono text-[11px]">
            <span className="text-jade-ink">{passed} passed</span>
            {failed > 0 ? <span className="text-crimson-ink">{failed} failed</span> : null}
            {skipped > 0 ? <span>{skipped} skipped</span> : null}
          </span>
        }
      />
      <div aria-hidden className="flex h-1 w-full bg-muted">
        <span className="bg-jade-solid" style={{ width: `${(passed / total) * 100}%` }} />
        <span className="bg-crimson-solid" style={{ width: `${(failed / total) * 100}%` }} />
      </div>
      <TraceContent>
        <div className="flex flex-col">
          {suites.map((suite) => (
            <SuiteRow key={suite.name} suite={suite} />
          ))}
        </div>
      </TraceContent>
    </Trace>
  )
}

function SuiteRow({ suite }: { suite: TestSuite }) {
  const failed = suite.tests.some((test) => test.status === "failed")
  return (
    <details open={failed} className="group/suite border-b border-border last:border-b-0">
      <summary className="flex cursor-pointer list-none items-center gap-2 px-3 py-2 outline-none select-none hover:bg-muted/50 focus-visible:bg-muted/50 [&::-webkit-details-marker]:hidden">
        <TraceStatusIcon status={failed ? "error" : "done"} />
        <span className="min-w-0 flex-1 truncate font-mono">{suite.name}</span>
        <span className="font-mono text-[11px] text-muted-foreground">{suite.tests.length}</span>
      </summary>
      <ul className="m-0 flex list-none flex-col gap-1 px-3 pb-2.5 ps-8">
        {suite.tests.map((test) => (
          <li key={test.name} className="flex flex-col gap-1">
            <span className="flex items-center gap-2">
              {test.status === "skipped" ? (
                <CircleDashedIcon aria-hidden className="size-3.5 shrink-0 text-muted-foreground" />
              ) : (
                <TraceStatusIcon status={toTrace[test.status]} />
              )}
              <span className={cn("min-w-0 flex-1 truncate", test.status !== "failed" && "text-muted-foreground")}>
                {test.name}
              </span>
              {test.duration !== undefined ? (
