"use client"

import * as React from "react"
import { createPortal } from "react-dom"
import { XIcon } from "lucide-react"

import { Button } from "@/components/ui/Button"
import { cn } from "@/lib/utils"

type TourStep = {
  /** CSS selector of the element to point at. Without one, the card is centered. */
  target?: string
  title: React.ReactNode
  description?: React.ReactNode
}

type Rect = { top: number; left: number; width: number; height: number }

const PADDING = 6
const CARD_WIDTH = 288
const GAP = 12

function measure(selector?: string): Rect | null {
  if (!selector) return null
  const element = document.querySelector(selector)
  if (!element) return null
  const rect = element.getBoundingClientRect()
  return {
    top: rect.top - PADDING,
    left: rect.left - PADDING,
    width: rect.width + PADDING * 2,
    height: rect.height + PADDING * 2,
  }
}

/**
 * Walks the reader through a page: dims everything but the current target
 * and sets a card beside it. The card is a modal dialog; focus moves into it,
 * Escape ends the tour, and focus goes back where it was.
 */
function Tour({
  steps,
  open,
  onOpenChange,
  step: stepProp,
  onStepChange,
  onFinish,
  labels = {},
}: {
  steps: TourStep[]
  open: boolean
  onOpenChange: (open: boolean) => void
  step?: number
  onStepChange?: (step: number) => void
  onFinish?: () => void
  labels?: {
    next?: string
    back?: string
    finish?: string
    skip?: string
    progress?: (step: number, total: number) => string
  }
}) {
  const [uncontrolledStep, setUncontrolledStep] = React.useState(0)
  const index = stepProp ?? uncontrolledStep
  const current = steps[index]
  const [rect, setRect] = React.useState<Rect | null>(null)
  const cardRef = React.useRef<HTMLDivElement>(null)
  const returnFocus = React.useRef<Element | null>(null)
  const titleId = React.useId()
  const descriptionId = React.useId()

  function setStep(next: number) {
    if (stepProp === undefined) setUncontrolledStep(next)
    onStepChange?.(next)
  }

  function close() {
    onOpenChange(false)
    setStep(0)
  }

  // Remember the trigger, and give focus back when the tour ends.
  React.useEffect(() => {
    if (!open) return
    returnFocus.current = document.activeElement
    return () => {
      ;(returnFocus.current as HTMLElement | null)?.focus?.()
    }
  }, [open])

  // Scroll the target into view, then follow it on scroll and resize.
  React.useLayoutEffect(() => {
    if (!open || !current) return
    const element = current.target ? document.querySelector(current.target) : null
    element?.scrollIntoView({ block: "center", behavior: "smooth" })
    const update = () => setRect(measure(current.target))
    update()
    const settle = setTimeout(update, 350)
    window.addEventListener("resize", update)
    window.addEventListener("scroll", update, true)
    return () => {
      clearTimeout(settle)
      window.removeEventListener("resize", update)
      window.removeEventListener("scroll", update, true)
    }
  }, [open, current])

  React.useEffect(() => {
    if (open) cardRef.current?.focus()
  }, [open, index])

  if (!open || !current || typeof document === "undefined") return null

  const last = index === steps.length - 1
  const viewportWidth = window.innerWidth
  const viewportHeight = window.innerHeight

  let cardStyle: React.CSSProperties
  if (rect) {
    const below = rect.top + rect.height + GAP
    const fitsBelow = below + 180 < viewportHeight
    const left = Math.min(
      Math.max(16, rect.left + rect.width / 2 - CARD_WIDTH / 2),
      viewportWidth - CARD_WIDTH - 16
    )
    cardStyle = fitsBelow
      ? { top: below, left }
      : { top: Math.max(16, rect.top - GAP), left, transform: "translateY(-100%)" }
  } else {
    cardStyle = { top: "50%", left: "50%", transform: "translate(-50%, -50%)" }
  }

  return createPortal(
    <div data-slot="tour" className="fixed inset-0 z-[110]">
      {/* The dim layer: a huge shadow around the cut-out, so the target stays clickable-looking and sharp. */}
      {rect ? (
        <div
          aria-hidden
          className="pointer-events-none fixed rounded-2xl transition-all duration-300 ease-out"
          style={{
            top: rect.top,
            left: rect.left,
            width: rect.width,
            height: rect.height,
            boxShadow: "0 0 0 9999px rgb(0 0 0 / 0.45)",
          }}
        />
      ) : (
        <div aria-hidden className="fixed inset-0 bg-black/45" />
      )}
      {/* Clicks outside the card do nothing, so a stray click does not end the tour. */}
      <div aria-hidden className="fixed inset-0" />

      <div
        ref={cardRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={current.description ? descriptionId : undefined}
        tabIndex={-1}
        onKeyDown={(event) => {
          if (event.key === "Escape") {
            event.preventDefault()
            close()
          }
          // Keep Tab inside the card.
          if (event.key === "Tab" && cardRef.current) {
            const focusable = cardRef.current.querySelectorAll<HTMLElement>("button")
            const first = focusable[0]
            const lastButton = focusable[focusable.length - 1]
            if (event.shiftKey && document.activeElement === first) {
              event.preventDefault()
              lastButton.focus()
            } else if (!event.shiftKey && document.activeElement === lastButton) {
              event.preventDefault()
              first.focus()
            }
          }
        }}
        data-slot="tour-card"
        className="fixed flex w-72 flex-col gap-3 rounded-[min(var(--radius-4xl),24px)] bg-popover p-4 text-popover-foreground shadow-lg ring-1 ring-foreground/5 outline-none transition-[top,left] duration-300 ease-out dark:ring-foreground/10"
        style={cardStyle}
      >
        <div className="flex items-start justify-between gap-3">
          <div className="space-y-1">
            <p className="m-0 font-mono text-[11px] text-muted-foreground tabular-nums">
              {labels.progress?.(index + 1, steps.length) ?? `${index + 1} of ${steps.length}`}
            </p>
            <h2 id={titleId} className="m-0 text-sm font-medium">
              {current.title}
            </h2>
          </div>
          <Button
            variant="ghost"
            size="icon-xs"
            aria-label={labels.skip ?? "Skip tour"}
            onClick={close}
            className="-me-1 text-muted-foreground"
          >
            <XIcon />
          </Button>
        </div>
        {current.description ? (
          <p id={descriptionId} className="m-0 text-xs leading-5 text-muted-foreground">
            {current.description}
          </p>
        ) : null}
        <div className="flex items-center gap-2">
          <span aria-hidden className="flex flex-1 gap-1">
            {steps.map((_, i) => (
              <span
                key={i}
                className={cn(
                  "h-1 rounded-full transition-all",
                  i === index ? "w-4 bg-foreground" : "w-1 bg-foreground/20"
                )}
              />
            ))}
          </span>
          {index > 0 ? (
            <Button variant="ghost" size="sm" onClick={() => setStep(index - 1)}>
              {labels.back ?? "Back"}
            </Button>
          ) : null}
          <Button
            size="sm"
            onClick={() => {
              if (last) {
                onFinish?.()
                close()
              } else {
                setStep(index + 1)
              }
            }}
          >
            {last ? (labels.finish ?? "Done") : (labels.next ?? "Next")}
          </Button>
        </div>
      </div>
    </div>,
    document.body
  )
}

export { Tour }
export type { TourStep }

"use client"

import * as React from "react"
import { Collapsible as CollapsiblePrimitive } from "@base-ui/react/collapsible"
import { CheckIcon, ChevronDownIcon, CircleAlertIcon, CircleIcon } from "lucide-react"

import { Spinner } from "@/components/ui/Spinner"
import { cn } from "@/lib/utils"


/*
 * Trace is the shape every agent step shares: an icon, a title, a status, and
 * a body that folds. Reasoning, Tool, Plan, Task, Queue, Chain of Thought and
 * Subagent are all built on it, so a thread of mixed steps reads as one list.
 */

type TraceStatus = "pending" | "running" | "done" | "error"

const statusLabel: Record<TraceStatus, string> = {
  pending: "Pending",
  running: "Running",
  done: "Done",
  error: "Failed",
}

/** Small status mark: an empty ring, a Spinner, a jade check, a crimson alert. */
function TraceStatusIcon({
  status,
  className,
}: {
  status: TraceStatus
  className?: string
}) {
  const base = cn("size-3.5 shrink-0", className)
  switch (status) {
    case "running":
      return <Spinner role={undefined} aria-label={undefined} aria-hidden className={base} />
    case "done":
      return <CheckIcon aria-hidden className={cn(base, "text-jade-ink")} />
    case "error":
      return <CircleAlertIcon aria-hidden className={cn(base, "text-crimson-ink")} />
    default:
      return <CircleIcon aria-hidden className={cn(base, "text-muted-foreground/60")} />
  }
}

type TraceContextValue = { status: TraceStatus; variant: "plain" | "card" }

const TraceContext = React.createContext<TraceContextValue>({ status: "done", variant: "plain" })

function useTrace() {
  return React.useContext(TraceContext)
}

/**
 * One step. `plain` reads inline in a message; `card` frames it, for tool
 * calls and subagents whose body holds code.
 */
function Trace({
  className,
  status = "done",
  variant = "plain",
  ...props
}: CollapsiblePrimitive.Root.Props & {
  status?: TraceStatus
  variant?: "plain" | "card"
}) {
  return (
    <TraceContext.Provider value={{ status, variant }}>
      <CollapsiblePrimitive.Root
        data-slot="trace"
        data-status={status}
        data-variant={variant}
        className={cn(
          "group/trace flex flex-col text-xs",
          variant === "card" && "overflow-hidden rounded-2xl border border-border bg-card",
          variant === "plain" && "gap-2",
          className
        )}
        {...props}
      />
    </TraceContext.Provider>
  )
}

/**
 * The row: icon, label, optional meta, status, chevron. The label shimmers
 * while the step runs. Children replace the label.
 */
function TraceTrigger({
  className,
  icon,
  label,
  meta,
  showStatus = true,
  statusLabels = statusLabel,
  children,
  ...props
}: CollapsiblePrimitive.Trigger.Props & {
  icon?: React.ReactNode
  label?: React.ReactNode
  /** Right-aligned detail: a duration, a count, a model. */
  meta?: React.ReactNode
  showStatus?: boolean
  statusLabels?: Record<TraceStatus, string>
}) {
  const { status, variant } = useTrace()

  return (
    <CollapsiblePrimitive.Trigger
      data-slot="trace-trigger"
      className={cn(
        "group/trace-trigger flex items-center gap-2 text-start text-muted-foreground outline-none",
        variant === "card"
          ? "w-full px-3 py-2 text-foreground hover:bg-muted/50 focus-visible:bg-muted/50"
          : "w-fit rounded-lg hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/30",
        "[&_svg:not([class*='size-'])]:size-3.5",
        className
      )}
      {...props}
    >
      {icon ? (
        <span aria-hidden className="flex shrink-0 text-muted-foreground">
          {icon}
        </span>
      ) : null}
      <span
        className={cn(
          "min-w-0 truncate",
          variant === "card" && "flex-1 font-medium",
          status === "running" && "shimmer"
        )}
      >
        {children ?? label}
      </span>
      {meta ? <span className="shrink-0 text-muted-foreground tabular-nums">{meta}</span> : null}
      {showStatus && variant === "card" ? (
        <span className="flex shrink-0 items-center gap-1.5 text-muted-foreground">
          <TraceStatusIcon status={status} />
          <span>{statusLabels[status]}</span>
        </span>
      ) : null}
      <ChevronDownIcon
        aria-hidden
        className="size-3.5! shrink-0 text-muted-foreground transition-transform duration-200 group-data-[panel-open]/trace-trigger:rotate-180"
      />
    </CollapsiblePrimitive.Trigger>
  )
}

function TraceContent({ className, children, ...props }: CollapsiblePrimitive.Panel.Props) {
  const { variant } = useTrace()

  return (
    <CollapsiblePrimitive.Panel
      data-slot="trace-content"
      className={cn(
        "h-(--collapsible-panel-height) overflow-hidden transition-[height] duration-200 data-ending-style:h-0 data-starting-style:h-0",
        className
      )}
      {...props}
    >
      <div
        className={cn(
          variant === "plain" && "border-s-2 border-border ps-3 text-muted-foreground",
          variant === "card" && "border-t border-border"
        )}
      >
        {children}
      </div>
    </CollapsiblePrimitive.Panel>
  )
}

/** A labelled block inside a card trace: Input, Output, Error. */
function TraceSection({
  className,
  label,
  children,
  ...props
}: React.ComponentProps<"div"> & { label?: React.ReactNode }) {
  return (
    <div
      data-slot="trace-section"
      className={cn("space-y-1.5 px-3 py-2.5 [&+&]:border-t [&+&]:border-border", className)}
      {...props}
    >
      {label ? (
        <div className="text-[11px] font-medium tracking-wide text-muted-foreground uppercase">
          {label}
        </div>
      ) : null}
      {children}
    </div>
  )
}

/** A sequence of steps on a rail, each with its own status. */
function TraceSteps({ className, ...props }: React.ComponentProps<"ol">) {
  return (
    <ol
      data-slot="trace-steps"
      className={cn("m-0 flex list-none flex-col p-0", className)}
      {...props}
    />
  )
}

function TraceStep({
  className,
  status = "done",
  title,
  description,
  children,
  ...props
}: Omit<React.ComponentProps<"li">, "title"> & {
  status?: TraceStatus
  title: React.ReactNode
  description?: React.ReactNode
}) {
  return (
    <li
      data-slot="trace-step"
      data-status={status}
      className={cn(
        "relative flex gap-2.5 pb-3 text-xs last:pb-0",
        // The rail joins this step's mark to the next one.
        "before:absolute before:start-[6.5px] before:top-5 before:bottom-0 before:w-px before:bg-border last:before:hidden",
        className
      )}
      {...props}
    >
      <span className="mt-0.5 flex size-3.5 shrink-0 items-center justify-center bg-background">
        <TraceStatusIcon status={status} />
      </span>
      <div className="flex min-w-0 flex-1 flex-col gap-1">
        <span
          className={cn(
            "leading-[1.125rem] text-foreground",
            status === "pending" && "text-muted-foreground",
            status === "done" && "text-muted-foreground",
            status === "running" && "shimmer"
          )}
        >
          {title}
        </span>
        {description ? <span className="text-muted-foreground">{description}</span> : null}
        {children}
      </div>
      <span className="sr-only">, {statusLabel[status]}</span>
    </li>
  )
}

export {
  Trace,
  TraceTrigger,
  TraceContent,
  TraceSection,
  TraceSteps,
  TraceStep,
  TraceStatusIcon,
  useTrace,
}
export type { TraceStatus }

"use client"

import * as React from "react"
import { ChevronRightIcon } from "lucide-react"

import { cn } from "@/lib/utils"

type TreeItem = {
  id: string
  label: React.ReactNode
  /** Plain text for typeahead when `label` is not a string. */
  textValue?: string
  icon?: React.ReactNode
  disabled?: boolean
  children?: TreeItem[]
}

type VisibleItem = {
  item: TreeItem
  level: number
  parentId: string | null
  posinset: number
  setsize: number
}

function flatten(
  items: TreeItem[],
  expanded: Set<string>,
  level = 1,
  parentId: string | null = null,
  out: VisibleItem[] = []
) {
  items.forEach((item, index) => {
    out.push({ item, level, parentId, posinset: index + 1, setsize: items.length })
    if (item.children?.length && expanded.has(item.id)) {
      flatten(item.children, expanded, level + 1, item.id, out)
    }
  })
  return out
}

function TreeView({
  className,
  items,
  value,
  defaultValue,
  onValueChange,
  expanded,
  defaultExpanded = [],
  onExpandedChange,
  ...props
}: Omit<React.ComponentProps<"ul">, "defaultValue" | "onChange"> & {
  items: TreeItem[]
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (id: string, item: TreeItem) => void
  expanded?: string[]
  defaultExpanded?: string[]
  onExpandedChange?: (expanded: string[]) => void
}) {
  const [uncontrolledValue, setUncontrolledValue] = React.useState(defaultValue ?? null)
  const [uncontrolledExpanded, setUncontrolledExpanded] = React.useState(defaultExpanded)
  const selected = value !== undefined ? value : uncontrolledValue
  const open = React.useMemo(
    () => new Set(expanded ?? uncontrolledExpanded),
    [expanded, uncontrolledExpanded]
  )
  const visible = React.useMemo(() => flatten(items, open), [items, open])
  const [focusedId, setFocusedId] = React.useState<string | null>(null)
  const refs = React.useRef(new Map<string, HTMLLIElement>())

  const tabStop =
    visible.find((entry) => entry.item.id === focusedId)?.item.id ??
    visible.find((entry) => entry.item.id === selected)?.item.id ??
    visible[0]?.item.id

  function setOpen(id: string, next: boolean) {
    const list = new Set(open)
    if (next) list.add(id)
    else list.delete(id)
    const result = Array.from(list)
    if (expanded === undefined) setUncontrolledExpanded(result)
    onExpandedChange?.(result)
  }

  function select(item: TreeItem) {
    if (item.disabled) return
    if (value === undefined) setUncontrolledValue(item.id)
    onValueChange?.(item.id, item)
  }

  function focus(id: string | undefined) {
    if (!id) return
    setFocusedId(id)
    refs.current.get(id)?.focus()
  }

  function onKeyDown(event: React.KeyboardEvent, entry: VisibleItem) {
    const index = visible.indexOf(entry)
    const { item } = entry
    const hasChildren = Boolean(item.children?.length)
    const isOpen = open.has(item.id)
    const rtl = getComputedStyle(event.currentTarget).direction === "rtl"
    const forward = rtl ? "ArrowLeft" : "ArrowRight"
    const back = rtl ? "ArrowRight" : "ArrowLeft"

    switch (event.key) {
      case "ArrowDown":
        focus(visible[index + 1]?.item.id)
        break
      case "ArrowUp":
        focus(visible[index - 1]?.item.id)
        break
      case "Home":
        focus(visible[0]?.item.id)
        break
      case "End":
        focus(visible[visible.length - 1]?.item.id)
        break
      case forward:
        if (hasChildren && !isOpen) setOpen(item.id, true)
        else if (hasChildren) focus(visible[index + 1]?.item.id)
        break
      case back:
        if (hasChildren && isOpen) setOpen(item.id, false)
        else focus(entry.parentId ?? undefined)
        break
      case "Enter":
      case " ":
        select(item)
        if (hasChildren && event.key === "Enter") setOpen(item.id, !isOpen)
        break
      default: {
        if (event.key.length !== 1 || event.metaKey || event.ctrlKey) return
        const char = event.key.toLowerCase()
        const ordered = [...visible.slice(index + 1), ...visible.slice(0, index + 1)]
        const match = ordered.find((candidate) => {
          const text =
            candidate.item.textValue ??
            (typeof candidate.item.label === "string" ? candidate.item.label : "")
          return text.toLowerCase().startsWith(char)
        })
        focus(match?.item.id)
        break
      }
    }
    event.preventDefault()
    event.stopPropagation()
  }

  function renderLevel(levelItems: TreeItem[], level: number): React.ReactNode {
    return levelItems.map((item) => {
      const entry = visible.find((candidate) => candidate.item.id === item.id)
      if (!entry) return null
      const hasChildren = Boolean(item.children?.length)
      const isOpen = open.has(item.id)
      const isSelected = selected === item.id

      return (
        <li
          key={item.id}
          ref={(node) => {
            if (node) refs.current.set(item.id, node)
            else refs.current.delete(item.id)
          }}
          role="treeitem"
          aria-level={level}
          aria-posinset={entry.posinset}
          aria-setsize={entry.setsize}
          aria-expanded={hasChildren ? isOpen : undefined}
          aria-selected={isSelected}
          aria-disabled={item.disabled || undefined}
          tabIndex={item.id === tabStop ? 0 : -1}
          data-slot="tree-view-item"
          onKeyDown={(event) => onKeyDown(event, entry)}
          onFocus={(event) => {
            if (event.target === event.currentTarget) setFocusedId(item.id)
          }}
          className="outline-none [&:focus-visible>[data-slot=tree-view-row]]:ring-3 [&:focus-visible>[data-slot=tree-view-row]]:ring-ring/30"
        >
          <div
            data-slot="tree-view-row"
            data-selected={isSelected ? "" : undefined}
            data-disabled={item.disabled ? "" : undefined}
            onClick={() => {
              focus(item.id)
              select(item)
              if (hasChildren) setOpen(item.id, !isOpen)
            }}
            style={{ paddingInlineStart: `calc(${level - 1} * 1rem + 0.5rem)` }}
            className={cn(
              "flex h-7 cursor-pointer items-center gap-1.5 rounded-xl pe-2 text-xs select-none hover:bg-muted",
              "data-selected:bg-muted data-selected:font-medium",
              "data-disabled:pointer-events-none data-disabled:opacity-50",
              "[&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-3.5"
            )}
          >
            <ChevronRightIcon
              aria-hidden
              className={cn(
                "text-muted-foreground transition-transform duration-150 rtl:rotate-180",
                isOpen && "rotate-90 rtl:rotate-90",
                !hasChildren && "invisible"
              )}
            />
            {item.icon ? (
              <span aria-hidden className="flex text-muted-foreground">
                {item.icon}
              </span>
            ) : null}
            <span className="min-w-0 truncate">{item.label}</span>
          </div>
          {hasChildren && isOpen ? (
            <ul role="group" className="m-0 list-none p-0">
              {renderLevel(item.children ?? [], level + 1)}
            </ul>
          ) : null}
        </li>
      )
    })
  }

  return (
    <ul
      role="tree"
      data-slot="tree-view"
      className={cn("m-0 flex list-none flex-col p-0", className)}
      {...props}
    >
      {renderLevel(items, 1)}
    </ul>
  )
}

export { TreeView }
export type { TreeItem }

